"""Chunked vs recurrent decode: bytes/s at 512/1024/2048/4096 context.

    uv run --extra gpu python scripts/bench_decode.py --out-dir checkpoints/real_small \
        --ckpt-name k5000

Two arms, ONE checkpoint, the same prompt bytes, the same `n` generated bytes and
the same temperature:

* `chunked` — `decode_bytes`: every generated byte re-forwards the last
  `max_seq_len` bytes, so a step costs `O(window)` and a reply `O(n · window)`.
* `recurrent` — `recurrent_decode`: the per-iteration KDA state is carried, so a
  step costs `O(1)` and the reply `O(prompt + n)`. Its prompt PREFILL is one
  step per prompt byte (there is no chunked prefill — see `model/decode.py`),
  and that prefill is INSIDE the reported time.

The `context` column is the PROMPT length. **Past the checkpoint's `max_seq_len`
the two arms are no longer the same function**: the chunked arm only ever sees
the last `max_seq_len` bytes (its window saturates, and so does its cost), while
the recurrent arm keeps the whole history — that is the "unbounded context" half
of the claim, and the table prints `max_seq_len` so a reader can see where the
comparison stops being like-for-like. `bytes/s` is `n / total wall clock`,
prefill included, and the `arm` column is the counters line (`kda_step` = the
fused decode kernel ran; `kda_step_torch` = the CPU recurrence; both zero would
mean no attention arm).

Machine discipline first (AGENTS 1.5): no `dormouse train`, no A/B battery
driver (`ab_*.py`), and < 1 GiB on the card. A busy card makes this script SKIP
loudly with exit 0 — while the trainer owns the GPU that is the correct answer,
not a failure. `--device cpu` bypasses the preflight (a CPU run measures the
HOST, not the card, and is for verifying the script, not for quoting a number).

**The checkpoint must be one whose snapshot the CURRENT config schema accepts.**
Every snapshot under `checkpoints/` predates the deletion of the six dead config
stubs (`0e7d25a`), so `_snapshot_run` refuses them all — a pre-existing condition
(`scripts/bench_spec.py` has the same wall), not this script's. Point
`--out-dir/--ckpt-name` at a fresh run's checkpoint.
"""

from __future__ import annotations

import argparse
import subprocess
import sys
import time
from pathlib import Path

import torch

from dormouse.cli import _snapshot_run
from dormouse.instrument import Counters
from dormouse.model import DormouseModel
from dormouse.model.decode import decode_bytes, recurrent_decode
from dormouse.train.loop import load_model_half, load_model_state

# `scripts/` is not a package (a test loads this file by path): the lane guard is
# a sibling file, so its directory goes on the path, APPENDED not inserted (a
# script name at the front of `sys.path` would shadow a package of that name).
sys.path.append(str(Path(__file__).resolve().parent))
from _lane import preflight  # noqa: E402

#: The context ladder the headline is quoted at (prompt bytes).
CONTEXTS = (512, 1024, 2048, 4096)


def prompt_of(length: int) -> bytes:
    """A deterministic prompt of `length` bytes (bytes 1..251, never the pad value)."""
    return bytes((i * 7 + 3) % 251 + 1 for i in range(length))


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--out-dir", default="checkpoints/real_small")
    ap.add_argument("--ckpt-name", default="k5000")
    ap.add_argument("--n", type=int, default=32, help="bytes generated per arm per context")
    ap.add_argument("--temp", type=float, default=0.8)
    ap.add_argument("--contexts", default=",".join(str(c) for c in CONTEXTS))
    ap.add_argument(
        "--device",
        default="cuda",
        help="cuda (the headline) or cpu (verifies the script; measures the host)",
    )
    args = ap.parse_args()
    dev = args.device

    if dev == "cuda":
        busy = subprocess.run(
            ["pgrep", "-af", r"ab_[a-z0-9_]*\.p[y]"], capture_output=True, text=True
        ).stdout.strip()
        reason = preflight("cuda") or (
            f"an A/B battery driver is live: {busy.splitlines()[0]}" if busy else None
        )
        if reason is None:
            # This driver's own ceiling is 1 GiB, tighter than the lane guard's 2.0:
            # a card already holding a second model is contended however idle it looks.
            smi = subprocess.run(
                ["nvidia-smi", "--query-gpu=memory.used", "--format=csv,noheader,nounits"],
                capture_output=True,
                text=True,
            ).stdout.strip()
            if smi and int(smi.split()[0]) >= 1024:
                mib = smi.split()[0]
                reason = f"the card already holds {mib} MiB (this driver's ceiling is 1024)"
        if reason is not None:
            print(f"[SKIP] {reason}")
            print(
                "[SKIP] ONE heavy thing at a time (AGENTS 1.5): a contended measurement is "
                "a measurement of the contention."
            )
            return 0
    else:
        print(
            f"[NOTE] --device {dev}: this measures the HOST, not the card — the s/byte "
            "SHAPE is the claim, the absolute rate is not a GPU number"
        )

    out_dir = Path(args.out_dir)
    run = _snapshot_run(out_dir, args.ckpt_name)
    model = DormouseModel(run.model).to(dev)
    # The ONE loader: an engram_ram checkpoint is host tables + `.ngram`.
    load_model_state(model, run.train, load_model_half(out_dir / f"{args.ckpt_name}.pt"))
    model.eval()
    params = sum(p.numel() for p in model.parameters())
    contexts = [int(c) for c in args.contexts.split(",")]
    print(
        f"[shape] {args.ckpt_name} · {params:,} params · max_seq_len "
        f"{run.model.max_seq_len} · max_iter {run.model.max_iter} · n {args.n} B · "
        f"temp {args.temp} · contexts {contexts}",
        flush=True,
    )

    def timed(arm: str, prompt: bytes, n_bytes: int) -> tuple[float, str]:
        gen = torch.Generator(device=dev).manual_seed(run.train.seed)
        counters = Counters()
        if dev == "cuda":
            torch.cuda.synchronize()
        t0 = time.perf_counter()
        with torch.no_grad():
            if arm == "chunked":
                decode_bytes(model, prompt, n_bytes, temp=args.temp, device=dev, generator=gen)
            else:
                recurrent_decode(
                    model,
                    prompt,
                    n_bytes,
                    temp=args.temp,
                    device=dev,
                    generator=gen,
                    counters=counters,
                )
        if dev == "cuda":
            torch.cuda.synchronize()
        return time.perf_counter() - t0, counters.line()

    # One warm pass pays the autotuner/compile before anything is timed.
    with torch.no_grad():
        recurrent_decode(model, prompt_of(8), 4, temp=args.temp, device=dev)
        decode_bytes(model, prompt_of(8), 4, temp=args.temp, device=dev)
    print("[warm] an 8-byte pass on both arms done (autotune/compile paid)", flush=True)

    rows: dict[tuple[int, str], tuple[float, float]] = {}
    print(
        f"{'context':>8} {'arm':>10} {'total B/s':>10} {'gen B/s':>9} {'gen s/byte':>11}  counters"
    )
    for ctx in contexts:
        prompt = prompt_of(ctx)
        for arm in ("chunked", "recurrent"):
            dt, line = timed(arm, prompt, args.n)
            # The MARGINAL rate: `2n` bytes with the same seed differs from `n` by
            # exactly the last `n` steps, so everything a call pays once — the
            # recurrent arm's one-step-per-byte prefill, the chunked arm's
            # first-window fill — cancels in the difference. That is the per-byte
            # generation rate; `total B/s` is the end-to-end one.
            dt2, _ = timed(arm, prompt, 2 * args.n)
            gen = args.n / max(dt2 - dt, 1e-9)
            rows[(ctx, arm)] = (args.n / max(dt, 1e-9), gen)
            print(
                f"{ctx:>8} {arm:>10} {args.n / max(dt, 1e-9):>10.1f} {gen:>9.1f} "
                f"{1e3 / max(gen, 1e-9):>10.1f}m  {line}",
                flush=True,
            )

    print("\n[headline] per-byte GENERATION rate, recurrent vs chunked (the `gen B/s` column)")
    for ctx in contexts:
        chunked = rows[(ctx, "chunked")][1]
        recurrent = rows[(ctx, "recurrent")][1]
        print(
            f"  context {ctx:>5}: chunked {chunked:>9.1f} B/s · recurrent {recurrent:>9.1f} "
            f"B/s · {recurrent / max(chunked, 1e-9):>6.2f}x"
        )
    print(
        "\nread it: `gen B/s` is the per-byte generation rate with the O(context) part\n"
        "of a call cancelled; `total B/s` charges the recurrent arm's prefill (one\n"
        "step per prompt byte) and the chunked arm's first-window fill. The chunked\n"
        f"arm's gen rate is ~flat once the context passes max_seq_len ({run.model.max_seq_len})\n"
        "because its window saturates; the recurrent arm's is flat at EVERY context\n"
        "(that is the O(1) claim) and its context is unbounded."
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
